contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        // First play: pot becomes 10 if no win, or 0 if win (contract balance tracks pot).
        c.play{value: amount}();
        uint potBefore = c.pot();
        uint balBefore = address(c).balance;
        // Deciding play with exact ticket.
        c.play{value: amount}();
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;
        if (potAfter == 0) {
            // A win pays out the entire pot (old pot + new ticket), so the
            // contract balance drops to exactly the pre-play balance minus
            // the pre-play pot (which is 0 on a fresh contract).
            assert(balAfter == balBefore - potBefore);
        } else {
            // No win: pot and balance each grew by exactly the ticket.
            assert(potAfter == potBefore + 10 && balAfter == balBefore + 10);
        }
    }
    receive() external payable {}
}

