        uint potAfter = c.pot();
        assert(
            !reverted
            && (potAfter == potBefore + amount
                || (potAfter == 0
                    && address(this).balance == selfBefore + potBefore + amount))
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        c.play{value: amount}();
        uint potBefore = c.pot();
        uint selfBefore = address(this).balance;
        require(potBefore <= selfBefore);
        bool reverted;
        try c.play{value: amount}() { reverted = false; }
        catch { reverted = true; }
        uint potAfter = c.pot();
        uint selfAfter = address(this).balance;
        assert(
            !reverted
            && (
                (potAfter == potBefore + amount
                    && selfAfter == selfBefore - amount)
                ||
                (potAfter == 0
                    && selfAfter == selfBefore + potBefore)
            )
        );
    }
    receive() external payable {}
}
